// Asegura la hoja CATALOGO_IMAGENES [modelo, conjunto_id, conjunto, imagen_url]
// con una fila por (modelo, conjunto). Crea la hoja si falta y agrega las filas
// de modelos/conjuntos nuevos sin pisar los links ya cargados.
function _asegurarHojaCatalogoImagenes() {
  var ss   = getDb();
  var hoja = ss.getSheetByName('CATALOGO_IMAGENES');
  if (!hoja) {
    hoja = ss.insertSheet('CATALOGO_IMAGENES');
    hoja.appendRow(['modelo', 'conjunto_id', 'conjunto', 'imagen_url']);
    hoja.setFrozenRows(1);
    hoja.getRange(1,1,1,4).setBackground('#00a3e0').setFontColor('#fff').setFontWeight('bold');
    hoja.setColumnWidth(3, 260); hoja.setColumnWidth(4, 420);
  }
  var datos = hoja.getDataRange().getValues();
  var existe = {};
  for (var i = 1; i < datos.length; i++) {
    existe[String(datos[i][0] || '').trim() + '|' + String(datos[i][1] || '').trim()] = true;
  }
  var nuevas = [];
  var mods = _CATALOGO_EXPLOTADAS.modelos || [];
  for (var m = 0; m < mods.length; m++) {
    for (var j = 0; j < mods[m].conjuntos.length; j++) {
      var c = mods[m].conjuntos[j];
      if (!existe[mods[m].modelo + '|' + c.id]) nuevas.push([mods[m].modelo, c.id, c.nombre, '']);
    }
  }
  if (nuevas.length) hoja.getRange(hoja.getLastRow() + 1, 1, nuevas.length, 4).setValues(nuevas);
  return hoja;
}

// Extrae el FILE_ID de cualquier formato de link de Drive:
//   .../file/d/ID/view  ·  ?id=ID  ·  lh3.googleusercontent.com/d/ID
// Devuelve '' si no encuentra un ID de Drive (se asume URL directa).
function _catDriveId(url) {
  var s = String(url || '').trim();
  if (!s) return '';
  var m = s.match(/\/d\/([-\w]{20,})/);        // /file/d/ID  |  lh3 /d/ID
  if (m) return m[1];
  m = s.match(/[?&]id=([-\w]{20,})/);           // open?id=ID | uc?id=ID | thumbnail?id=ID
  if (m) return m[1];
  return '';
}

// Devuelve todos los modelos con sus conjuntos + los links de imagen
// mergeados desde CATALOGO_IMAGENES (clave modelo|conjunto_id), normalizados
// a URL incrustable.
function obtenerCatalogoExplotadas() {
  try {
    var urlMap = {};
    try {
      var hoja  = _asegurarHojaCatalogoImagenes();
      var datos = hoja.getDataRange().getValues();
      for (var i = 1; i < datos.length; i++) {
        var mdl = String(datos[i][0] || '').trim();
        var cid = String(datos[i][1] || '').trim();
        var raw = String(datos[i][3] || '').trim();
        if (cid) urlMap[mdl + '|' + cid] = raw;
      }
    } catch(eU) { Logger.log('obtenerCatalogoExplotadas urls: ' + eU); }

    var modelos = [];
    var mods = _CATALOGO_EXPLOTADAS.modelos || [];
    for (var mi = 0; mi < mods.length; mi++) {
      var M = mods[mi];
      var conj = [];
      for (var j = 0; j < M.conjuntos.length; j++) {
        var c   = M.conjuntos[j];
        var raw = urlMap[M.modelo + '|' + c.id] || '';
        var id  = _catDriveId(raw);
        var imagenUrl = id ? ('https://lh3.googleusercontent.com/d/' + id + '=w1600') : raw;
        conj.push({
          id: c.id, nombre: c.nombre, nImgs: c.nImgs,
          imagenUrl: imagenUrl,
          imagenId:  id,
          totalItems: c.items.length,
          items: c.items
        });
      }
      modelos.push({ modelo: M.modelo, modeloNombre: M.modeloNombre, conjuntos: conj });
    }
    return { ok: true, modelos: modelos };
  } catch(e) {
    Logger.log('obtenerCatalogoExplotadas: ' + e);
    return { ok: false, error: e.toString(), modelos: [] };
  }
}
